import React, { useState } from 'react';

export interface ContactFormProps {
  initial_name?: string;
  initial_email?: string;
  submitting?: boolean;
  server_error?: string;
  onSubmit?: (payload: { name: string; email: string; message: string }) => void;
  onValidationFailed?: (payload: { fields: string[] }) => void;
}

const ContactForm: React.FC<ContactFormProps> = ({
  initial_name = '',
  initial_email = '',
  submitting = false,
  server_error,
  onSubmit,
  onValidationFailed,
}) => {
  const [name, setName] = useState<string>(initial_name);
  const [email, setEmail] = useState<string>(initial_email);
  const [message, setMessage] = useState<string>('');

  const validate = (): string[] => {
    const invalid: string[] = [];
    if (!name.trim()) invalid.push('name');
    const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email.trim() || !emailRe.test(email)) invalid.push('email');
    if (!message || message.length < 10) invalid.push('message');
    return invalid;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (submitting) return;
    const invalid = validate();
    if (invalid.length > 0) {
      onValidationFailed?.({ fields: invalid });
      return;
    }
    onSubmit?.({ name, email, message });
  };

  return (
    <form onSubmit={handleSubmit} className="contact-form">
      <h2>Kontaktformular</h2>
      <div>
        <label htmlFor="cf-name">Name</label>
        <input
          id="cf-name"
          type="text"
          value={name}
          onChange={(e) => setName(e.target.value)}
          disabled={submitting}
        />
      </div>
      <div>
        <label htmlFor="cf-email">E-Mail</label>
        <input
          id="cf-email"
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          disabled={submitting}
        />
      </div>
      <div>
        <label htmlFor="cf-message">Nachricht</label>
        <textarea
          id="cf-message"
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          disabled={submitting}
        />
      </div>
      {server_error && (
        <div role="alert" className="server-error">
          {server_error}
        </div>
      )}
      <button type="submit" disabled={submitting}>
        {submitting ? 'Senden…' : 'Absenden'}
      </button>
    </form>
  );
};

export default ContactForm;
